  }

  async receiveMessage(envelope) {
    this.inbox.push(envelope);
    console.log(`\n💬 [${this.id}] 메시지 수신 완료`);
  }

  async processInbox() {
    if (this.inbox.length === 0) {
      console.log(`[${this.id}] 받은 메시지 없음`);
      return null;
    }

